/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
for (const reducedMotion of ['no-preference', 'reduce']) {
  const context = await browser.newContext({ reducedMotion })
  const page = await context.newPage()
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  await page.goto('http://localhost:3000/')
  await page.waitForTimeout(250)
  const imageName = await page.locator('.product-image').first().evaluate(el => getComputedStyle(el).viewTransitionName)
  await page.evaluate(() => {
    window.samples = []
    window.sampleTimer = setInterval(() => {
      const animations = document.getAnimations({ subtree: true }).map(a => ({
        pseudo: a.effect?.pseudoElement || '',
        name: a.animationName || '',
        duration: a.effect?.getTiming().duration
      })).filter(a => a.pseudo.includes('view-transition'))
      if (animations.length) window.samples.push(animations)
    }, 10)
  })
  await page.locator('.product-card').first().click()
  await page.waitForURL('**/product/classic-sneakers')
  const heroName = await page.locator('.product-hero').evaluate(el => getComputedStyle(el).viewTransitionName)
  await page.waitForTimeout(550)
  const forward = await page.evaluate(() => { clearInterval(window.sampleTimer); return window.samples.flat() })
  await page.evaluate(() => {
    window.samples = []
    window.sampleTimer = setInterval(() => {
      const animations = document.getAnimations({ subtree: true }).map(a => ({
        pseudo: a.effect?.pseudoElement || '',
        name: a.animationName || '',
        duration: a.effect?.getTiming().duration
      })).filter(a => a.pseudo.includes('view-transition'))
      if (animations.length) window.samples.push(animations)
    }, 10)
  })
  await page.locator('.back-link').click()
  await page.waitForURL('http://localhost:3000/')
  await page.waitForTimeout(550)
  const back = await page.evaluate(() => { clearInterval(window.sampleTimer); return window.samples.flat() })
  const summarize = events => [...new Map(events.map(a => ["'`${a.pseudo}|${a.name}|${a.duration}`, a])).values()]
  console.log(JSON.stringify({ reducedMotion, imageName, heroName, forward: summarize(forward), back: summarize(back), errors }))
  await context.close()
}
await browser.close()
EOF'

/bin/bash -lc "node --input-type=module <<'EOF'
for (const path of ['/', '/product/classic-sneakers', '/product/no-such-product']) {
  const response = await fetch("'`http://localhost:3000${path}`)
  const html = await response.text()
  console.log(path, response.status, { title: html.includes('"'Product Gallery'), sharedName: html.includes('product-image-classic-sneakers'), details: html.includes('Timeless design meets everyday comfort.') })
}
EOF"
